    # color 1 in the corresponding right-side column. Pieces are read by position.
    h, w = len(grid), len(grid[0])
    seen = set()
    pieces = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
