            stack = [(r, c)]; seen.add((r, c)); cells = []
            while stack:
                a, b = stack.pop(); cells.append((a, b))
                for x, y in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
                    if 0 <= x < h and 0 <= y < w and grid[x][y] == 2 and (x,y) not in seen:
                        seen.add((x,y)); stack.append((x,y))
            if len(cells) == 4:
                minr = min(a for a,b in cells); minc = min(b for a,b in cells)
                shape = {(a-minr,b-minc) for a,b in cells}
                pieces.append((minr, minc, shape))
    out = [[0]*6 for _ in range(3)]
    # Order by top-to-bottom, left-to-right; each piece occupies successive code columns.
    for i, (_, _, shape) in enumerate(sorted(pieces)):
