                        stack.append((x,y))
            if len(cells) != 4:
                continue
            top = min(a for a,b in cells)
            left = min(b for a,b in cells)
            shape = {(a-top,b-left) for a,b in cells}
            up = shape == {(0,1),(1,0),(1,1),(1,2)}
            down = shape == {(0,0),(0,1),(0,2),(1,1)}
