    # The T shapes are symbols in a reduced 3x6 layout. Their vertical
    # placement selects the output row, orientation selects the half, and
    # their order within each row selects the column.
    h, w = len(grid), len(grid[0])
    seen = set()
    groups = {0: [], 1: [], 2: []}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]; seen.add((r, c)); cells = []
            while stack:
                a, b = stack.pop(); cells.append((a, b))
                for x, y in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
                    if 0 <= x < h and 0 <= y < w and grid[x][y] == 2 and (x,y) not in seen:
                        seen.add((x,y)); stack.append((x,y))
            if len(cells) != 4: continue
            top = min(a for a,b in cells); left = min(b for a,b in cells)
            shape = {(a-top,b-left) for a,b in cells}
            if shape == {(0,1),(1,0),(1,1),(1,2)}:
                color, side = 3, 0
            elif shape == {(0,0),(0,1),(0,2),(1,1)}:
                color, side = 1, 3
            else: continue
            row = min(2, top * 3 // h)
            groups[row].append((left, side, color))
    out = [[0] * 6 for _ in range(3)]
    for row, pieces in groups.items():
        for index, (left, side, color) in enumerate(sorted(pieces)):
            col = index % 3
            out[row][side + col] = color
    return out
