    # Four-cell T tokens: up-pointing -> 3 and down-pointing -> 1. Their
    # row-major token order determines sequential positions in a 3x6 display,
    # with orientation selecting the left or right three columns.
    h, w = len(grid), len(grid[0])
    seen = set()
    tokens = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r,c) in seen:
                continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                a,b=stack.pop(); cells.append((a,b))
                for x,y in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
                    if 0<=x<h and 0<=y<w and grid[x][y]==2 and (x,y) not in seen:
                        seen.add((x,y)); stack.append((x,y))
            if len(cells)!=4: continue
            top=min(a for a,b in cells); left=min(b for a,b in cells)
            shape={(a-top,b-left) for a,b in cells}
            if shape=={(0,1),(1,0),(1,1),(1,2)}: tokens.append((top,left,3))
            elif shape=={(0,0),(0,1),(0,2),(1,1)}: tokens.append((top,left,1))
    out=[[0]*6 for _ in range(3)]
    for i,(_,_,color) in enumerate(sorted(tokens)):
